import java.util.HashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> book = new HashMap<>();
        book.put("{a}", 3);
        book.put("{b}", 5);
        book.put("{a}", {u});
        System.out.println("账本上有 " + book.size() + " 个名字");
        System.out.println("{a} 那一行是 " + book.get("{a}"));
        System.out.println("大肥鱼 那一行是 " + book.get("大肥鱼"));
        System.out.println("大肥鱼 兜底之后是 " + book.getOrDefault("大肥鱼", {d}));
    }
}
